Using the frozen Brief and approved skeleton, write a complete ExperimentalMusicSpec. Preserve the skeleton's identity and section plan while realizing concrete notes, rests, velocities and useful CC. Output only the complete spec JSON.


FROZEN BRIEF:
{
  "id": "l2-electronic-groove",
  "level": "L2",
  "title": "Broken-grid electronic groove",
  "purpose": "A loopable groove for a product-film montage that feels engineered but not mechanical.",
  "duration_seconds": 24,
  "section_plan": [
    "establish: 4 bars",
    "variation: 4 bars"
  ],
  "style": [
    "left-field electronic",
    "syncopated",
    "clean"
  ],
  "mood": [
    "focused",
    "kinetic",
    "controlled"
  ],
  "must_include": [
    "kick and bass do not mask every downbeat",
    "one syncopated signature accent",
    "variation changes density"
  ],
  "must_avoid": [
    "four-on-the-floor throughout",
    "random fills",
    "continuous maximum density"
  ],
  "instrument_roles": [
    "kick and percussion",
    "sub bass",
    "chord stab",
    "short motif"
  ],
  "delivery": [
    "8 bars",
    "4 to 5 tracks",
    "drum notes remain in a practical GM range"
  ],
  "score_focus": [
    "groove",
    "low-end relationship",
    "variation"
  ],
  "mode_a": true
}

SKELETON:
{"title":"Broken-grid electronic groove","tempo_map":[{"bar":1,"bpm":80}],"key_map":[{"bar":1,"key":"A minor"}],"sections":[{"id":"est","start_bar":1,"num_bars":4},{"id":"var","start_bar":5,"num_bars":4}],"track_plan":[{"id":"drums","name":"Kick and Percussion","role":"drums","register":{"low":35,"high":82},"instrument_hint":"Electronic Drum Kit","section_jobs":[{"section_id":"est","intent":"Syncopated kick, sparse percussion accents, leave space on some downbeats","density":"sparse"},{"section_id":"var","intent":"Adds a signature offbeat accent and a few extra percussion hits, retains gaps","density":"medium"}]},{"id":"bass","name":"Sub Bass","role":"bass","register":{"low":28,"high":43},"instrument_hint":"Sub Bass","section_jobs":[{"section_id":"est","intent":"Short low-note phrases locking with but not masking every downbeat; rests on beat 4 often","density":"sparse"},{"section_id":"var","intent":"Slightly more movement with an additional octave-up note and rhythmic variation","density":"medium"}]},{"id":"chords","name":"Chord Stab","role":"harmony","register":{"low":48,"high":76},"instrument_hint":"PWM Chord Stab","section_jobs":[{"section_id":"est","intent":"Staccato chords on offbeats with clean two-note or three-note voicings, regular but not continuous","density":"medium"},{"section_id":"var","intent":"Chords become sparser, leaving more room for motif and accent; occasional sustained stab","density":"sparse"}]},{"id":"motif","name":"Short Motif","role":"melody","register":{"low":60,"high":84},"instrument_hint":"FM Pluck","section_jobs":[{"section_id":"est","intent":"Three-note syncopated motif appears twice with slight variation, avoids downbeats","density":"sparse"},{"section_id":"var","intent":"Motif repeats a step higher and adds one extra note; becomes the main focus","density":"medium"}]}],"motif_strategy":"Three-note motif built on A minor pentatonic, syncopated to land just after beat 2 and before beat 4; varied by transposition and one added note in the second section.","harmony_strategy":"A minor with v-i and iv-i movement; chord stabs voiced with open fifths and minor thirds to stay clean, sparser in variation to open space.","groove_strategy":"Broken grid: kick on 1, 1.75, and 2.5 in places but never four-on-the-floor; syncopated offbeats and rests keep it kinetic, while variation adds a signature accent on the 'and' of 3."}

